// Lê o evento da uazapi e decide se ele entra no fluxo de feedback.
// Entra só mensagem de TEXTO ou ÁUDIO, de cliente, em conversa individual.
// Devolve UM item com o que importa, ou nenhum item (o fluxo para aqui).
const body = $input.first().json.body || {};
const m = body.message || {};
const parar = [];

if (body.EventType !== 'messages') return parar;
// Grupo e mensagem do próprio número (o dono no celular ou a resposta automática).
if (m.isGroup === true || m.fromMe === true) return parar;
// Edição de uma mensagem já enviada não é mensagem nova.
if (typeof m.edited === 'string' && m.edited.trim() !== '') return parar;

const token = String(body.token || '').trim();
const baseUrl = String(body.BaseUrl || '').trim().replace(/\/+$/, '');
const messageId = String(m.messageid || '').trim();
if (!token || !/^https:\/\//i.test(baseUrl) || !messageId) return parar;

// Telefone do cliente: a conversa individual (...@s.whatsapp.net). Na conversa
// no formato novo do WhatsApp (...@lid), o telefone real vem em sender_pn.
const jid = [m.chatid, m.sender_pn]
  .map((v) => String(v || ''))
  .find((v) => v.endsWith('@s.whatsapp.net'));
if (!jid) return parar;
const telefone = jid.split('@')[0].replace(/\D/g, '');
if (telefone.length < 10 || telefone.length > 15) return parar;

// Clique no botão do anonimato (ramo da equipe). A uazapi manda o id do botão
// em buttonOrListid; se o id vier como texto, vale igual. Qualquer tipo de
// mensagem serve: o que identifica o clique é o id.
const ESCOLHAS = { equipe_anonimo: 'anonimo', equipe_mostrar: 'identificado' };
const botao = [m.buttonOrListid, m.text].map((v) => String(v || '').trim()).find((v) => ESCOLHAS[v]);
if (botao) {
  return [{ json: { token, baseUrl, messageId, telefone, tipo: 'botao', texto: '', escolha: ESCOLHAS[botao] } }];
}

// Só texto e áudio. Foto, vídeo, figurinha, reação, documento etc. não entram.
let tipo = null;
let texto = '';
if (m.messageType === 'AudioMessage') {
  tipo = 'audio';
} else if (m.messageType === 'Conversation' || m.messageType === 'ExtendedTextMessage') {
  tipo = 'texto';
  texto = (typeof m.text === 'string' ? m.text : '').trim();
  if (!texto) return parar;
} else {
  return parar;
}

return [{ json: { token, baseUrl, messageId, telefone, tipo, texto: texto.slice(0, 4000) } }];

// A conta pode receber feedback agora? O restaurante foi achado pelo token
// da instância. Precisa: onboarding completo, assinatura ativa e conta não excluída.
const r = $input.first().json;
if (!r.id || r.excluida_em || r.onboarding_completo !== true || r.assinatura_status !== 'ativa') return [];

return [{
  json: {
    ...$('Lê a mensagem').first().json,
    restauranteId: r.id,
    nomeRestaurante: String(r.nome_restaurante || '').trim(),
    // Número de contato/suporte das Configurações (só dígitos) — nulo = não indicar.
    telefoneContato: String(r.telefone_contato || '').replace(/\D/g, '') || null,
  },
}];

// Áudio transcrito vira texto como qualquer outra mensagem. Se o download ou
// a transcrição falharam, o fluxo para em silêncio (não há o que analisar).
const t = String($input.first().json.text || '').trim();
if (!t) return [];
return [{ json: { ...$('Restaurante ativo?').first().json, texto: t.slice(0, 4000) } }];

// Junta as mensagens que a pessoa mandou em sequência.
// Cada mensagem espera 20 s; só segue quem for a ÚLTIMA da conversa naquele
// momento — se chegou outra depois, é ela que vai juntar tudo.
const meu = $('Guarda no buffer').first().json;
const linhas = $input.all().map((i) => i.json).filter((r) => r.id != null);
if (!linhas.length) return [];

linhas.sort((a, b) => Number(a.id) - Number(b.id));
const ultima = linhas[linhas.length - 1];
if (Number(ultima.id) !== Number(meu.id)) return [];

// A uazapi às vezes entrega o mesmo evento duas vezes: tira as repetidas.
// Cada mensagem guarda o id dela: é por ele que a resposta cita (responde no
// WhatsApp) a mensagem certa e que todas ficam marcadas como lidas.
const vistos = new Set();
const mensagens = [];
for (const r of linhas) {
  let d = r.message_data;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  const id = d && d.messageid;
  if (id) {
    if (vistos.has(id)) continue;
    vistos.add(id);
  }
  const t = String(r.message_content || '').trim();
  if (t) mensagens.push({ id: id ? String(id) : '', texto: t.slice(0, 2000) });
}
const textoCompleto = mensagens.map((m) => m.texto).join('\n').slice(0, 6000).trim();
if (!textoCompleto) return [];
// Para a IA, cada mensagem com o número dela ([1], [2]...): ela diz de qual
// mensagem veio cada ponto e a pergunta.
const textoParaIA = mensagens.map((m, i) => `[${i + 1}] ${m.texto}`).join('\n').slice(0, 7000);
const ids = mensagens.map((m) => m.id).filter(Boolean);

return [{ json: { ...$('Restaurante ativo?').first().json, textoCompleto, textoParaIA, mensagens, ids, ateId: Number(ultima.id), remoteId: meu.remote_id } }];

// Valida o que a IA devolveu e decide: o que gravar e o que responder.
// Quem responde é a Helena, do atendimento do restaurante, com mensagens
// prontas sorteadas (seção 4).
// Regras:
//   - Feedback (há pelo menos um ponto)  -> grava e agradece.
//   - Pergunta/pedido COMPLETO sobre o restaurante -> indica o número de
//     contato das Configurações, só o número, sem link (sem número: só avisa
//     que o canal é de feedback). Pergunta incompleta ("tenho uma dúvida"),
//     em que não dá para saber o assunto, não é respondida.
//   - Feedback + pergunta                 -> agradece e encaminha, em mensagens
//     separadas, cada uma respondendo (citando) a mensagem de que fala.
//   - PARAR marcado pelo caminho do PARAR -> "Pronto, não vou mais te mandar
//     essas novidades." (só isso), respondendo a mensagem do PARAR.
//   - Qualquer outra coisa (saudação sozinha, "obrigado", assunto fora do
//     restaurante)                         -> não responde.
const base = $('Sou a última mensagem?').first().json;
// As mensagens juntadas, na ordem ([1], [2]... para a IA).
const mensagens = Array.isArray(base.mensagens) ? base.mensagens : [];
const numero = (v) => {
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= mensagens.length ? n : 0;
};

const CATEGORIAS = ['Comida', 'Bebidas', 'Atendimento', 'Ambiente', 'Limpeza', 'Preço', 'Tempo de Espera',
  'Reserva', 'Estacionamento', 'Acessibilidade', 'Música/Som', 'Cardápio/Variedade', 'Higiene', 'Outros'];
const semAcento = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

// 1. A resposta da IA (modo JSON) vira objeto.
const bruto = String($input.first().json.text || '');
let r = null;
try {
  r = JSON.parse(bruto);
} catch (e) {
  const achado = bruto.match(/\{[\s\S]*\}/);
  if (achado) {
    try { r = JSON.parse(achado[0]); } catch (e2) { r = null; }
  }
}
if (!r || typeof r !== 'object' || Array.isArray(r)) {
  // Sem formato não dá para gravar nem responder com segurança: a execução
  // fica marcada como erro no n8n para alguém ver.
  throw new Error('A IA devolveu algo fora do formato: ' + bruto.slice(0, 300));
}

// 2. Pontos válidos: categoria da lista fixa e um dos 4 sentimentos.
//    Neutro e Sugestão são valores distintos e nunca viram um no outro.
const sentimentoDoPonto = (valor) => {
  const v = semAcento(valor);
  if (v.includes('negativ')) return 'Negativo';
  if (v.includes('sugest')) return 'Sugestão';
  if (v.includes('positiv')) return 'Positivo';
  if (v.includes('neutr')) return 'Neutro';
  return null;
};
// O número que vai na frente de cada mensagem ([1], [2]...) não é do cliente.
const semNumero = (s) => String(s || '').replace(/^\s*\[\d+\]\s*/, '').trim();
const pontos = [];
let msgFeedback = 0; // a primeira mensagem com feedback: é ela que o agradecimento cita
for (const p of Array.isArray(r.pontos) ? r.pontos : []) {
  if (!p || typeof p !== 'object') continue;
  const sentimento = sentimentoDoPonto(p.sentimento);
  if (!sentimento) continue;
  const categoria = CATEGORIAS.find((c) => semAcento(c) === semAcento(p.categoria)) || 'Outros';
  const texto = semNumero(p.feedback_original);
  const resumo = semNumero(p.resumo);
  if (!texto && !resumo) continue;
  pontos.push({
    texto_original: (texto || resumo).slice(0, 1000),
    categoria,
    sentimento,
    resumo: (resumo || texto).slice(0, 120),
  });
  const n = numero(p.mensagem);
  if (n && (!msgFeedback || n < msgFeedback)) msgFeedback = n;
}

// 3. Sentimento da mensagem inteira (mesma ordem da feedbacks_originais_view):
//    positivo e negativo > negativo > positivo > sugestão > neutro.
const tem = (s) => pontos.some((p) => p.sentimento === s);
let sentimentoGeral = null;
if (pontos.length) {
  if (tem('Positivo') && tem('Negativo')) sentimentoGeral = 'Positivo e Negativo';
  else if (tem('Negativo')) sentimentoGeral = 'Negativo';
  else if (tem('Positivo')) sentimentoGeral = 'Positivo';
  else if (tem('Sugestão')) sentimentoGeral = 'Sugestão';
  else sentimentoGeral = 'Neutro';
}
const ehFeedback = pontos.length > 0;
// Só encaminha pergunta completa: sem o assunto, não dá para dizer com o que
// o número de contato ajuda — e "tenho uma dúvida" sozinho fica sem resposta.
const sobre = String(r.assunto_pergunta || '').trim().replace(/[.!?;:]+$/, '');
const temPergunta = (semAcento(r.tipo) === 'pergunta_restaurante' || r.tem_pergunta_restaurante === true) && sobre !== '';

// 4. O texto da resposta: mensagens prontas, escritas do jeito que uma pessoa
//    escreve no WhatsApp, sorteadas conforme o sentimento. A Helena se
//    apresenta na primeira resposta do dia. A IA só completa pedaços curtos
//    ({problema}, {elogio}, {ideia});
//    se um pedaço vier estranho, o sorteio fica só com as mensagens que não
//    usam ele. O cliente não é chamado pelo nome: o nome do perfil do
//    WhatsApp muitas vezes não é o nome real nem está escrito certo.
const sortear = (lista) => lista[Math.floor(Math.random() * lista.length)];

// Pedaço vindo da IA: curto, minúsculo, começando com artigo ("a pizza fria").
const trecho = (v) => {
  const t = String(v || '').trim().replace(/[.!?;:,]+$/, '');
  if (!t || t.length > 45 || t.split(/\s+/).length > 7) return '';
  if (!/^(a|o|as|os) [a-zà-ÿ0-9]/.test(t)) return '';
  if (/[.!?;:"“”()]|https?:|\d{4,}/.test(t)) return '';
  return t;
};
// "por" + "a pizza fria" = "pela pizza fria"; "de" + "o garçom" = "do garçom".
const CONTRACOES = {
  por: { a: 'pela', o: 'pelo', as: 'pelas', os: 'pelos' },
  de: { a: 'da', o: 'do', as: 'das', os: 'dos' },
};
const contrai = (prep, t) => {
  if (!t) return '';
  const partes = t.split(' ');
  return CONTRACOES[prep][partes[0]] + ' ' + partes.slice(1).join(' ');
};
const elogio = trecho(r.elogio);
const problema = trecho(r.problema);
const ideia = trecho(r.ideia);

// "do Camelo", mas "da Pizzaria Bella".
const restaurante = String(base.nomeRestaurante || '').trim();
const FEMININOS = ['pizzaria', 'cantina', 'churrascaria', 'padaria', 'lanchonete', 'casa', 'hamburgueria',
  'sorveteria', 'cafeteria', 'confeitaria', 'trattoria', 'osteria', 'esfiharia', 'pastelaria', 'tapiocaria',
  'creperia', 'doceria', 'adega', 'choperia', 'chopperia', 'cervejaria', 'peixaria', 'petiscaria', 'galeteria',
  'marmitaria', 'cozinha', 'tasca', 'taberna', 'bodega', 'panificadora', 'sanduicheria', 'temakeria',
  'pamonharia', 'brasa', 'vila', 'toca', 'esquina', 'fazenda', 'quinta', 'barraca', 'tenda', 'cabana'];
const primeiraPalavra = semAcento(restaurante.split(/\s+/)[0] || '');
const doRestaurante = restaurante
  ? (FEMININOS.includes(primeiraPalavra) ? 'da ' : 'do ') + restaurante
  : 'do restaurante';

// O número vai só com dígitos e o 55 na frente (5511987654321): sem
// parênteses, sem hífen e sem link.
const contato = base.telefoneContato ? (base.telefoneContato.length <= 11 ? '55' + base.telefoneContato : base.telefoneContato) : '';

const VARS = {
  doRestaurante,
  elogio,
  doElogio: contrai('de', elogio),
  peloProblema: contrai('por', problema),
  doProblema: contrai('de', problema),
  daIdeia: contrai('de', ideia),
  sobre,
  contato,
};
// Uma mensagem só entra no sorteio se tiver tudo o que ela usa.
const cabe = (m) => [...m.matchAll(/\{(\w+)\}/g)].every((x) => VARS[x[1]]);
const escolher = (lista) => sortear(lista.filter(cabe)).replace(/\{(\w+)\}/g, (_, k) => VARS[k]);

// A Helena se apresenta só na primeira resposta do dia para essa pessoa (o nó
// "Já respondeu hoje?" não achou resposta do número desde o início do dia).
// Nas outras, vai direto ao assunto, sem cumprimento.
const apresentar = !$('Já respondeu hoje?').first().json.id;
const APRESENTACAO = [
  'Oi! Aqui é a Helena, {doRestaurante}.',
  'Oi, tudo bem? Aqui é a Helena, {doRestaurante}.',
  'Olá! Sou a Helena, {doRestaurante}.',
  'Oi! Eu sou a Helena, {doRestaurante}.',
];

// Uma quebra de linha onde uma pessoa quebraria: a reação numa linha, o resto
// na outra.
const MENSAGENS = {
  positivo: [
    'Que bom que você gostou!\nObrigada por mandar mensagem, volta sempre 😊',
    'Fiquei muito feliz com sua mensagem!\nVou mostrar pro pessoal aqui, eles vão adorar.',
    'Ahh, que bom saber!\nObrigada pelo carinho, viu? Te esperamos de volta.',
    'Obrigada por contar!\nBom demais saber que deu tudo certo 😊',
    'Que alegria ler isso!\nVou repassar pra equipe agora mesmo. Volta sempre!',
    'Muito obrigada!\nMensagem assim faz o dia da gente aqui 😊',
    'Que bom que você gostou {doElogio}!\nVou contar pro pessoal, eles vão ficar felizes.',
    'Obrigada!\nVou passar o elogio {doElogio} pro pessoal, eles vão adorar saber.',
    'Que bom ler isso sobre {elogio}!\nObrigada por contar, volta sempre 😊',
  ],
  negativo: [
    'Poxa, sinto muito. Não era pra ter sido assim.\nObrigada por avisar, já passei pro pessoal responsável.',
    'Nossa, desculpa mesmo.\nVou falar com a equipe hoje ainda pra ver o que aconteceu.',
    'Que chato, sinto muito por isso.\nObrigada por contar, já deixei anotado pro pessoal.',
    'Poxa, me desculpa.\nObrigada pela sinceridade, vou repassar pra equipe agora.',
    'Sinto muito mesmo.\nJá passei sua mensagem pro pessoal daqui, obrigada por avisar.',
    'Puxa, que pena. Desculpa pelo transtorno.\nVou levar isso pro pessoal responsável.',
    'Poxa, sinto muito {peloProblema}.\nObrigada por avisar, já passei pro pessoal responsável.',
    'Nossa, desculpa {peloProblema}!\nVou falar com a equipe pra ver o que aconteceu.',
    'Que chato isso {doProblema}, desculpa mesmo.\nJá repassei pro pessoal daqui.',
    'Sinto muito {peloProblema}.\nObrigada por contar, vou levar isso pra equipe hoje.',
  ],
  misto: [
    'Obrigada por contar tudo!\nFico feliz com o que você gostou e sinto muito pelo que não foi legal. Vou passar pro pessoal.',
    'Que bom que teve coisa boa!\nE desculpa pelo que deixou a desejar, já repassei pra equipe.',
    'Obrigada pela sinceridade!\nAnotei o que você gostou e o que precisa melhorar, vou passar tudo pro pessoal.',
    'Obrigada por avisar!\nVou mostrar os elogios e as reclamações pro pessoal aqui.',
    'Que bom que você gostou {doElogio}!\nE desculpa {peloProblema}, já passei pro pessoal responsável.',
    'Obrigada por contar!\nFico feliz com {elogio} e sinto muito {peloProblema}. Vou falar com a equipe.',
    'Obrigada pelo retorno!\nQue bom que teve coisa boa, e desculpa {peloProblema}. Vou levar pra equipe.',
  ],
  neutro: [
    'Obrigada por contar como foi!\nVou passar pro pessoal aqui.',
    'Valeu pelo retorno!\nJá anotei aqui pra equipe.',
    'Obrigada pela opinião!\nAjuda muito a gente a melhorar.',
    'Obrigada por mandar mensagem!\nAnotei aqui e vou repassar pro pessoal.',
    'Que bom que você escreveu!\nVou mostrar pra equipe, obrigada.',
    'Anotado!\nObrigada por compartilhar com a gente.',
  ],
  sugestao: [
    'Adorei a sugestão, obrigada!\nVou passar pro pessoal aqui.',
    'Obrigada pela sugestão!\nJá anotei e vou levar pra equipe.',
    'Que ideia boa!\nVou repassar pro pessoal, obrigada por sugerir.',
    'Anotado!\nObrigada pela sugestão, vou mostrar pra equipe.',
    'Adorei a ideia {daIdeia}!\nVou passar pro pessoal aqui, obrigada.',
    'Obrigada pela sugestão {daIdeia}!\nJá anotei pra equipe.',
    'Que ideia boa essa {daIdeia}!\nVou levar pro pessoal, obrigada 😊',
  ],
};
// Sugestão que veio junto de outro sentimento: uma linha a mais.
const TAMBEM_SUGESTAO = [
  'Ah, e anotei sua sugestão também!',
  'E obrigada pela ideia {daIdeia}, vou passar adiante.',
  'Sua sugestão também ficou anotada, viu?',
];
// Pergunta sobre o restaurante: o canal é só de opinião; indica o contato.
const ENCAMINHA_JUNTO = [
  'Sobre {sobre}, por aqui eu não consigo te ajudar, esse número é só pra receber a opinião dos clientes.',
  'Ah, sobre {sobre}: esse número é só pra opiniões, então por aqui eu não consigo te ajudar.',
];
const ENCAMINHA_SO = [
  'Esse número é só pra receber a opinião dos clientes sobre o restaurante, então com {sobre} eu não consigo te ajudar por aqui.',
  'Por aqui eu só recebo a opinião dos clientes sobre o restaurante, então com {sobre} não consigo te ajudar.',
];
const PELO_CONTATO = [
  'Pra isso é só chamar a gente no número {contato}.',
  'Mas é só chamar a gente no número {contato}.',
];
const CENARIO = {
  'Positivo e Negativo': 'misto',
  Negativo: 'negativo',
  Positivo: 'positivo',
  'Sugestão': 'sugestao',
  Neutro: 'neutro',
};

// 5. O que sai: UMA mensagem para cada coisa (o agradecimento do feedback, o
//    encaminhamento da pergunta, a confirmação do PARAR), cada uma
//    respondendo (citando) no WhatsApp a mensagem do cliente de que fala, na
//    ordem em que ele escreveu. A apresentação vai no começo da primeira.
const encaminhamento = (lista) => escolher(lista) + (contato ? '\n' + escolher(PELO_CONTATO) : '');

// O caminho do PARAR roda antes (fica acima no canvas). Marcou o cliente
// agora? Se não rodou ou falhou, segue sem a confirmação.
let parar = null;
try {
  const marcado = $('Marca para não receber').first().json;
  if (marcado && marcado.marcou === true) parar = { n: numero($('Pediu para parar?').first().json.ordem) };
} catch (e) {
  parar = null;
}
// Se a "pergunta" é o próprio pedido para parar, não ganha o "esse número é
// só pra opiniões".
const perguntaEhParar = /parar|receber|mensage|novidade|atualiza|lista/.test(semAcento(sobre));

const saidas = [];
if (ehFeedback) {
  const cenario = CENARIO[sentimentoGeral];
  let corpo = escolher(MENSAGENS[cenario]);
  if (cenario !== 'sugestao' && tem('Sugestão')) corpo += '\n' + escolher(TAMBEM_SUGESTAO);
  saidas.push({ tipo: 'feedback', n: msgFeedback, texto: corpo });
}
if (temPergunta && !(parar && perguntaEhParar)) {
  saidas.push({ tipo: 'pergunta', n: numero(r.mensagem_pergunta), texto: encaminhamento(ehFeedback ? ENCAMINHA_JUNTO : ENCAMINHA_SO) });
}
if (parar) saidas.push({ tipo: 'parar', n: parar.n, texto: 'Pronto, não vou mais te mandar essas novidades.' });

// Na ordem das mensagens do cliente; na mesma mensagem: feedback, pergunta,
// PARAR. Sem o número (a IA não disse), o feedback vai primeiro e a pergunta
// depois dele.
const POSICAO = { feedback: 0, pergunta: 1, parar: 2 };
const chave = (s) => s.n || (s.tipo === 'feedback' ? 0 : mensagens.length + 1);
saidas.sort((a, b) => chave(a) - chave(b) || POSICAO[a.tipo] - POSICAO[b.tipo]);

// A confirmação do PARAR é só a frase dela: nunca leva a apresentação.
if (apresentar && saidas.length && saidas[0].tipo !== 'parar') {
  saidas[0].texto = escolher(APRESENTACAO) + '\n\n' + saidas[0].texto;
}

// A mensagem do cliente que cada resposta cita. Se ele mandou uma só, é ela.
const citada = (n) => {
  const m = mensagens[(n || (mensagens.length === 1 ? 1 : 0)) - 1];
  return m && m.id ? String(m.id) : '';
};
// "Digitando..." antes de cada uma, do tempo de alguém escrever aquele texto,
// sorteado (entre 3 e 12 segundos), para não ter cara de robô.
const digitando = (t) => Math.min(12000, Math.max(3000,
  Math.round(t.length * (35 + Math.random() * 25)) + 1000 + Math.floor(Math.random() * 2000)));
const respostas = saidas.map((s) => ({ texto: s.texto, replyid: citada(s.n), digitandoMs: digitando(s.texto) }));

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    token: base.token,
    textoCompleto: base.textoCompleto,
    ehFeedback,
    sentimentoGeral,
    pontos,
    // Uma por item no envio, uma de cada vez. `resposta` junta todas, só
    // para ler na execução do n8n.
    respostas,
    resposta: respostas.map((x) => x.texto).join('\n\n'),
  },
}];

// Um item por ponto, já ligado à mensagem original que acabou de ser salva.
const r = $('Monta a resposta').first().json;
const origemId = $input.first().json.id;
if (!origemId) throw new Error('A mensagem original não foi salva (sem id).');
return r.pontos.map((p) => ({
  json: {
    texto_original: p.texto_original,
    categoria: p.categoria,
    sentimento: p.sentimento,
    resumo: p.resumo,
    telefone_cliente: r.telefone,
    restaurante_id: r.restauranteId,
    origem_id: origemId,
  },
}));

// Um item por mensagem que sai, já na ordem. O laço depois manda uma de cada
// vez: a próxima só começa o "digitando..." quando a anterior já foi.
const r = $('Monta a resposta').first().json;
return (r.respostas || []).map((m) => ({ json: m }));

// Mensagem com cara de "parar de receber"? Só um filtro barato: quem decide
// de verdade é a IA do "Decide se é para parar", olhando a conversa.
// "para" no meio da frase (fui lá para comemorar) não passa; "Para!" sozinho
// numa linha passa. Olha cada mensagem juntada: a última com cara de "parar"
// é a que a confirmação vai responder (citar).
const base = $input.first().json;
const normal = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const PADROES = [
  /\bparar\b/,
  /\bpare(m)?\b/,
  /\bpara(m)? de (me )?(mandar|enviar|mand|envi)/,
  /\bnao (quero|queria|desejo|preciso) (mais )?(receber|essas|esses|mensage|recado|novidade|atualiza)/,
  /\bnao (me )?(mande|mandem|envie|enviem|manda|envia)\b/,
  /\bnao receber (mais|essas|esses|as |os |mensage|recado|novidade|atualiza)/,
  /\bnao (precisa|precisam) (mais )?(me )?(avisar|mandar|enviar)/,
  /\bchega de (mensage|recado|novidade|atualiza)/,
  /\b(descadastr|desinscrev)/,
  /\bsair da lista\b/,
  /\b(me )?(tira|tirem|remove|removam|retira) (o meu numero|meu numero|da lista)/,
  /\b(cancelar|cancela|cancele) (o |os |as |essas |esses )?(meu numero|minha inscricao|mensage|aviso|atualiza|novidade|recado)/,
  /^\s*(stop|sair|cancelar|descadastrar|parar|pare|para)\s*[.!]*\s*$/m,
];
const pede = (t) => PADROES.some((p) => p.test(normal(t)));

const mensagens = Array.isArray(base.mensagens) && base.mensagens.length
  ? base.mensagens
  : [{ id: '', texto: base.textoCompleto }];
let ordem = 0;
mensagens.forEach((m, i) => { if (pede(m.texto)) ordem = i + 1; });
if (!ordem) return [];

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    textoCompleto: base.textoCompleto,
    baseUrl: base.baseUrl,
    token: base.token,
    ordem,
    mensagemId: String(mensagens[ordem - 1].id || ''),
    // Funcionário cadastrado na Equipe: o PARAR dele é dos pedidos de opinião.
    daEquipe: !!(base.equipe && base.equipe.funcionarioId),
  },
}];

// O que a IA precisa para decidir: a mensagem nova, a conversa recente com o
// restaurante e a última atualização mandada. Quem já parou ou não é contato
// das atualizações (nunca entrou na lista) não tem o que marcar.
const base = $('Pediu para parar?').first().json;
const ctx = $input.first().json || {};
if (!ctx.contato_id || ctx.ja_parou === true) return [];

const hora = (d) => d
  ? new Date(d).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
  : '';
const limpo = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);

// Funcionário (ramo da equipe): as "atualizações" são os pedidos de opinião.
const daEquipe = base.daEquipe === true;
const QUEM = daEquipe ? 'FUNCIONÁRIO' : 'CLIENTE';

const conversa = (Array.isArray(ctx.conversa) ? ctx.conversa : [])
  .map((m) => `[${hora(m.enviada_em)}] ${m.quem === 'restaurante' ? 'RESTAURANTE' : QUEM}: ${limpo(m.texto, 300)}`);
const ult = ctx.ultima_atualizacao && ctx.ultima_atualizacao.texto ? ctx.ultima_atualizacao : null;

const linhas = daEquipe ? [
  'ATENÇÃO: quem escreve aqui é um FUNCIONÁRIO do restaurante, não um cliente. As "atualizações" deste caso são os pedidos de opinião que o restaurante manda para a equipe; todo pedido termina avisando que ele pode responder PARAR. Pedido sobre o TRABALHO ("quero parar de trabalhar no domingo", "parem de me escalar à noite", "para de me cobrar") NÃO é pedido para parar as mensagens.',
  '',
  'MENSAGEM NOVA DO FUNCIONÁRIO (é sobre ela que você decide):',
  limpo(base.textoCompleto, 1500),
  '',
  'CONVERSA RECENTE (da mais antiga para a mais nova; a mensagem nova pode já aparecer no fim):',
  conversa.length ? conversa.join('\n') : '(nenhuma mensagem anterior registrada)',
  '',
  ult
    ? `ÚLTIMO PEDIDO DE OPINIÃO QUE O RESTAURANTE MANDOU (${hora(ult.enviada_em)}): ${limpo(ult.texto, 600)}`
    : 'O restaurante ainda não mandou nenhum pedido de opinião para esse funcionário.',
] : [
  'MENSAGEM NOVA DO CLIENTE (é sobre ela que você decide):',
  limpo(base.textoCompleto, 1500),
  '',
  'CONVERSA RECENTE (da mais antiga para a mais nova; a mensagem nova pode já aparecer no fim):',
  conversa.length ? conversa.join('\n') : '(nenhuma mensagem anterior registrada)',
  '',
  ult
    ? `ÚLTIMA ATUALIZAÇÃO QUE O RESTAURANTE MANDOU (${hora(ult.enviada_em)}): ${limpo(ult.texto, 600)}`
    : 'O restaurante ainda não mandou nenhuma atualização para esse cliente.',
  ctx.aviso_parar_em
    ? `O restaurante já avisou esse cliente (em ${hora(ctx.aviso_parar_em)}) que ele pode responder PARAR para não receber mais as atualizações.`
    : 'O cliente ainda não recebeu o aviso de que pode responder PARAR.',
];

return [{ json: { ...base, contexto: linhas.join('\n') } }];

// Só marca quando a IA disse que é pedido para parar, com certeza alta.
// Resposta fora do formato, dúvida ou "não": não marca nada.
const base = $('Monta o contexto').first().json;
const bruto = String($input.first().json.text || '');
let r = null;
try { r = JSON.parse(bruto); } catch (e) {
  const achado = bruto.match(/\{[\s\S]*\}/);
  if (achado) { try { r = JSON.parse(achado[0]); } catch (e2) { r = null; } }
}
if (!r || r.parar !== true || String(r.certeza || '').toLowerCase() !== 'alta') return [];

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    token: base.token,
    motivo: String(base.textoCompleto || '').replace(/\s+/g, ' ').trim().slice(0, 300),
    daEquipe: base.daEquipe === true,
  },
}];

// Quem escreveu é da equipe do restaurante? (função equipe_quem_e)
// Para o cliente nada muda: este nó só acrescenta `equipe` (nulo) e `escolha`
// (nula) ao que o "Sou a última mensagem?" montou. Se a consulta falhar, trata
// como cliente: o fluxo de sempre não pode parar por causa da equipe.
const base = $('Sou a última mensagem?').first().json;
const q = $input.first().json || {};
const equipe = q.ok === true && q.funcionario_id
  ? {
      funcionarioId: q.funcionario_id,
      nome: String(q.nome || ''),
      podeEscolher: q.pode_escolher === true,
      aguardandoEscolha: q.aguardando_escolha === true,
    }
  : null;

// A pessoa respondeu POR ESCRITO à pergunta do anonimato? (o botão pode não
// aparecer em todo celular). Só vale quando a mensagem inteira é a resposta.
let escolha = null;
if (equipe && (equipe.podeEscolher || equipe.aguardandoEscolha)) {
  const t = String(base.textoCompleto || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\b(por favor|pfv|pf|obrigad[oa]|valeu|vlw|ok|ta bom|blz|beleza)\b/g, ' ')
    .replace(/\s+/g, ' ').trim();
  const MOSTRAR = [
    /^(pode |podem |quero |sim )?(mostrar|mostra|aparecer|identificar)( (o )?meu nome)?( sim)?$/,
    /^com (o )?(meu )?nome$/,
    /^nao (precisa|quero) (ser |ficar )?(anonim[oa]|anonimato)$/,
    /^pode (falar|dizer|colocar|por|botar) (o )?(meu )?nome$/,
  ];
  const ANONIMO = [
    /^(eu )?(quero |prefiro |pode |deixa |sim )?(ficar |ser |fica |deixa |como |em |no )*(anonim[oa]|anonimato|anonimamente)( mesmo| sim)?$/,
    /^sem (o )?(meu )?nome$/,
    /^nao (quero |pode |precisa )?(mostrar|mostra|aparecer|identificar)( (o )?meu nome)?$/,
  ];
  if (t && t.split(' ').length <= 8) {
    if (MOSTRAR.some((p) => p.test(t))) escolha = 'identificado';
    else if (ANONIMO.some((p) => p.test(t))) escolha = 'anonimo';
    // "Quer que sua resposta fique anônima?" → "sim" / "não" soltos só valem
    // enquanto a pergunta está no ar.
    else if (equipe.aguardandoEscolha && /^(sim|s|quero|quero sim|sim quero|isso|claro)$/.test(t)) escolha = 'anonimo';
    else if (equipe.aguardandoEscolha && /^(nao|n|nao precisa|nao quero)$/.test(t)) escolha = 'identificado';
  }
}

return [{ json: { ...base, equipe, escolha } }];

// Valida o que a IA devolveu sobre a mensagem de um FUNCIONÁRIO e decide o que
// gravar e o que responder. Mesma lógica do "Monta a resposta" dos clientes:
//   - Feedback (há pelo menos um ponto)  -> grava (sem telefone) e agradece.
//   - Pergunta para este canal            -> responde com texto pronto.
//   - PARAR marcado pelo caminho do PARAR -> "Pronto, não vou mais te mandar
//     essas mensagens." (só isso).
//   - Qualquer outra coisa                -> não responde.
// A pergunta do anonimato (o botão) sai depois, no "Respostas da equipe".
const base = $('Sou a última mensagem?').first().json;
const mensagens = Array.isArray(base.mensagens) ? base.mensagens : [];
const numero = (v) => {
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= mensagens.length ? n : 0;
};

const CATEGORIAS = ['Liderança e gestão', 'Salário e benefícios', 'Escala e horários', 'Carga de trabalho', 'Clima e colegas', 'Estrutura e equipamentos', 'Treinamento e crescimento', 'Reconhecimento', 'Comunicação', 'Segurança e saúde', 'Clientes', 'Outros'];
const semAcento = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

// 1. A resposta da IA vira objeto.
const bruto = String($input.first().json.text || '');
let r = null;
try {
  r = JSON.parse(bruto);
} catch (e) {
  const achado = bruto.match(/\{[\s\S]*\}/);
  if (achado) {
    try { r = JSON.parse(achado[0]); } catch (e2) { r = null; }
  }
}
if (!r || typeof r !== 'object' || Array.isArray(r)) {
  throw new Error('A IA devolveu algo fora do formato: ' + bruto.slice(0, 300));
}

// 2. Pontos válidos: categoria da lista da equipe e um dos 4 sentimentos.
const sentimentoDoPonto = (valor) => {
  const v = semAcento(valor);
  if (v.includes('negativ')) return 'Negativo';
  if (v.includes('sugest')) return 'Sugestão';
  if (v.includes('positiv')) return 'Positivo';
  if (v.includes('neutr')) return 'Neutro';
  return null;
};
const semNumero = (s) => String(s || '').replace(/^\s*\[\d+\]\s*/, '').trim();
const pontos = [];
let msgFeedback = 0;
for (const p of Array.isArray(r.pontos) ? r.pontos : []) {
  if (!p || typeof p !== 'object') continue;
  const sentimento = sentimentoDoPonto(p.sentimento);
  if (!sentimento) continue;
  const categoria = CATEGORIAS.find((c) => semAcento(c) === semAcento(p.categoria)) || 'Outros';
  const texto = semNumero(p.feedback_original);
  const resumo = semNumero(p.resumo);
  if (!texto && !resumo) continue;
  pontos.push({
    texto_original: (texto || resumo).slice(0, 1000),
    categoria,
    sentimento,
    resumo: (resumo || texto).slice(0, 120),
  });
  const n = numero(p.mensagem);
  if (n && (!msgFeedback || n < msgFeedback)) msgFeedback = n;
}

// 3. Sentimento da mensagem inteira (mesma ordem dos clientes).
const tem = (s) => pontos.some((p) => p.sentimento === s);
let sentimentoGeral = null;
if (pontos.length) {
  if (tem('Positivo') && tem('Negativo')) sentimentoGeral = 'Positivo e Negativo';
  else if (tem('Negativo')) sentimentoGeral = 'Negativo';
  else if (tem('Positivo')) sentimentoGeral = 'Positivo';
  else if (tem('Sugestão')) sentimentoGeral = 'Sugestão';
  else sentimentoGeral = 'Neutro';
}
const ehFeedback = pontos.length > 0;
// Relato grave (assédio, discriminação, ameaça, risco): fica anônimo se a
// pessoa não responder a pergunta, e a resposta indica onde pedir ajuda.
const sensivel = ehFeedback && r.sensivel === true;
const sobreBruto = semAcento(r.pergunta_sobre);
const sobre = sobreBruto === 'anonimato' ? 'anonimato' : sobreBruto === 'quem_e' ? 'quem_e' : 'outro';
const temPergunta = semAcento(r.tipo) === 'pergunta' || r.tem_pergunta === true;

// 4. Os textos: mensagens prontas, do jeito da Helena.
const sortear = (lista) => lista[Math.floor(Math.random() * lista.length)];
const restaurante = String(base.nomeRestaurante || '').trim();
const FEMININOS = ['pizzaria', 'cantina', 'churrascaria', 'padaria', 'lanchonete', 'casa', 'hamburgueria',
  'sorveteria', 'cafeteria', 'confeitaria', 'trattoria', 'osteria', 'esfiharia', 'pastelaria', 'tapiocaria',
  'creperia', 'doceria', 'adega', 'choperia', 'chopperia', 'cervejaria', 'peixaria', 'petiscaria', 'galeteria',
  'marmitaria', 'cozinha', 'tasca', 'taberna', 'bodega', 'panificadora', 'sanduicheria', 'temakeria',
  'pamonharia', 'brasa', 'vila', 'toca', 'esquina', 'fazenda', 'quinta', 'barraca', 'tenda', 'cabana'];
const primeiraPalavra = semAcento(restaurante.split(/\s+/)[0] || '');
const doRestaurante = restaurante
  ? (FEMININOS.includes(primeiraPalavra) ? 'da ' : 'do ') + restaurante
  : 'do restaurante';

// Ela se apresenta só na primeira resposta do dia (o pedido de feedback que
// saiu hoje já conta: o "Já respondeu hoje?" acha ele).
const apresentar = !$('Já respondeu hoje?').first().json.id;
const APRESENTACAO = [
  'Oi! Aqui é a Helena, ' + doRestaurante + '.',
  'Oi, tudo bem? Aqui é a Helena, ' + doRestaurante + '.',
  'Olá! Sou a Helena, ' + doRestaurante + '.',
];

const MENSAGENS = {
  positivo: [
    'Que bom saber disso!\nObrigada por contar, vou passar pra gestão.',
    'Fico feliz de ler isso!\nObrigada por dividir, já deixei anotado.',
    'Ahh, que bom!\nObrigada por contar, ajuda a gente a manter o que tá dando certo.',
    'Obrigada por contar!\nBom demais saber que isso tá funcionando.',
  ],
  negativo: [
    'Obrigada por confiar e contar.\nIsso é importante, já deixei anotado pra gestão olhar.',
    'Poxa, sinto muito por isso.\nObrigada por falar, vou levar pra gestão.',
    'Entendi, obrigada pela sinceridade.\nJá anotei aqui pra quem cuida disso ver.',
    'Que chato, sinto muito.\nObrigada por avisar, isso vai pra gestão.',
  ],
  misto: [
    'Obrigada por contar o que vai bem e o que incomoda.\nJá anotei tudo pra gestão.',
    'Valeu pela sinceridade!\nAnotei o que tá bom e o que precisa melhorar.',
    'Obrigada por contar tudo.\nVou passar os dois lados pra gestão.',
  ],
  neutro: [
    'Obrigada por responder!\nJá anotei aqui.',
    'Valeu por contar!\nVou passar pra gestão.',
    'Obrigada!\nFica anotado.',
  ],
  sugestao: [
    'Boa ideia, obrigada!\nJá anotei pra gestão ver.',
    'Obrigada pela sugestão!\nVou levar pra quem decide.',
    'Gostei da ideia!\nFica anotada, obrigada.',
  ],
};
const TAMBEM_SUGESTAO = [
  'Ah, e anotei sua sugestão também!',
  'Sua sugestão também ficou anotada, viu?',
];
const RELATO_GRAVE = 'Obrigada por confiar em contar isso.\nÉ um assunto sério e já está registrado.\n\nSe precisar de ajuda agora, o Ligue 180 e o Disque 100 atendem de graça, 24 horas.';
const RESPONDE_PERGUNTA = {
  anonimato: 'Você que escolhe!\nDepois que você mandar sua opinião, eu pergunto se quer que ela fique anônima. Se ficar, no sistema do restaurante aparece o que você disse, sem o seu nome.',
  quem_e: 'Sou a Helena, do atendimento ' + doRestaurante + '.\nPor aqui eu recebo o que a equipe quiser contar sobre o trabalho.',
  outro: 'Por aqui eu só recebo a opinião da equipe sobre o trabalho, então com isso eu não consigo te ajudar.\nO melhor é falar direto com a gerência.',
};
const CENARIO = {
  'Positivo e Negativo': 'misto',
  Negativo: 'negativo',
  Positivo: 'positivo',
  'Sugestão': 'sugestao',
  Neutro: 'neutro',
};

// 5. O que sai: uma mensagem para cada coisa, na ordem em que a pessoa escreveu.
// O caminho do PARAR roda antes (fica acima no canvas). Marcou agora?
let parar = null;
try {
  const marcado = $('Marca para não receber').first().json;
  if (marcado && marcado.marcou === true) parar = { n: numero($('Pediu para parar?').first().json.ordem) };
} catch (e) {
  parar = null;
}

const saidas = [];
if (ehFeedback) {
  let corpo;
  if (sensivel) {
    corpo = RELATO_GRAVE;
  } else {
    const cenario = CENARIO[sentimentoGeral];
    corpo = sortear(MENSAGENS[cenario]);
    if (cenario !== 'sugestao' && tem('Sugestão')) corpo += '\n' + sortear(TAMBEM_SUGESTAO);
  }
  saidas.push({ tipo: 'feedback', n: msgFeedback, texto: corpo });
}
// Pergunta sobre "como parar" já é o próprio PARAR: não ganha outra resposta.
if (temPergunta && !parar) {
  saidas.push({ tipo: 'pergunta', n: numero(r.mensagem_pergunta), texto: RESPONDE_PERGUNTA[sobre], sobre });
}
if (parar) saidas.push({ tipo: 'parar', n: parar.n, texto: 'Pronto, não vou mais te mandar essas mensagens.' });

const POSICAO = { feedback: 0, pergunta: 1, parar: 2 };
const chave = (s) => s.n || (s.tipo === 'feedback' ? 0 : mensagens.length + 1);
saidas.sort((a, b) => chave(a) - chave(b) || POSICAO[a.tipo] - POSICAO[b.tipo]);

// A confirmação do PARAR nunca leva a apresentação; "Sou a Helena" depois de
// "Aqui é a Helena" ficaria repetido.
if (apresentar && saidas.length && saidas[0].tipo !== 'parar' && !(saidas[0].tipo === 'pergunta' && saidas[0].sobre === 'quem_e')) {
  saidas[0].texto = sortear(APRESENTACAO) + '\n\n' + saidas[0].texto;
}

const citada = (n) => {
  const m = mensagens[(n || (mensagens.length === 1 ? 1 : 0)) - 1];
  return m && m.id ? String(m.id) : '';
};
const digitando = (t) => Math.min(12000, Math.max(3000,
  Math.round(t.length * (35 + Math.random() * 25)) + 1000 + Math.floor(Math.random() * 2000)));
const respostas = saidas.map((s) => ({ tipo: s.tipo, texto: s.texto, replyid: citada(s.n), digitandoMs: digitando(s.texto) }));

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    token: base.token,
    textoCompleto: base.textoCompleto,
    ehFeedback,
    sentimentoGeral,
    pontos,
    sensivel,
    respostas,
    resposta: respostas.map((x) => x.texto).join('\n\n'),
  },
}];

// Um item por mensagem que sai para o funcionário, já na ordem, e a pergunta
// do anonimato (o botão), que vai depois de todas.
const m = $('Monta a resposta da equipe').first().json;
let gravado = null;
try { gravado = $('Grava o feedback da equipe').first().json; } catch (e) { gravado = null; }
const gravou = !!(gravado && gravado.ok === true);

// Era feedback e não foi gravado (a pessoa saiu do cadastro no meio do
// caminho): não agradece o que não guardou.
let respostas = Array.isArray(m.respostas) ? m.respostas : [];
if (m.ehFeedback && !gravou) respostas = respostas.filter((x) => x.tipo !== 'feedback');
if (!respostas.length) return [];

// A pergunta sai uma vez por leva de mensagens (o banco diz quando perguntar).
const perguntar = gravou && gravado.perguntar_identidade === true;
let pergunta = null;
if (perguntar) {
  const horas = Number(gravado.prazo_horas) > 0 ? Number(gravado.prazo_horas) : 24;
  const prazo = horas % 24 === 0 && horas > 24 ? (horas / 24) + ' dias' : horas + ' horas';
  // Relato grave nunca ganha o nome sozinho: sem resposta, fica anônimo.
  const rodape = gravado.sensivel === true
    ? 'Sem resposta, fica anônima.'
    : 'Sem resposta em ' + prazo + ', aparece com o seu nome.';
  const explica = 'Quer que sua resposta fique anônima?\nSe ficar, no sistema do restaurante aparece o que você disse, mas não o seu nome.';
  pergunta = {
    texto: explica + '\n\nSe os botões não aparecerem, é só responder ANÔNIMO ou MOSTRAR.',
    botoes: ['Ficar anônimo|equipe_anonimo', 'Mostrar meu nome|equipe_mostrar'],
    rodape,
    // Se o envio com botão falhar, a mesma pergunta vai como texto.
    textoSemBotao: explica + '\n\nResponda ANÔNIMO ou MOSTRAR.\n' + rodape,
    digitandoMs: 2500 + Math.floor(Math.random() * 2500),
  };
}

return respostas.map((x) => ({
  json: { texto: x.texto, replyid: x.replyid, digitandoMs: x.digitandoMs, perguntar, pergunta },
}));

// A escolha da identidade chega por dois caminhos: o clique no botão (direto
// da entrada, sem esperar o buffer) e a resposta por escrito ("anônimo",
// "pode mostrar"), depois do buffer. Aqui os dois ficam com a mesma cara.
let base = null;
try { base = $('Junta quem escreveu').first().json; } catch (e) { base = null; }
if (!base || !base.escolha) base = $('Restaurante ativo?').first().json;
if (!base || !['anonimo', 'identificado'].includes(base.escolha)) return [];

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    token: base.token,
    escolha: base.escolha,
  },
}];

// Confirma a escolha para a pessoa. Só quando mudou alguma coisa: clique
// repetido, o mesmo evento entregue duas vezes ou quem não tem nada a escolher
// ficam em silêncio.
const p = $('Prepara a escolha').first().json;
const r = $input.first().json || {};
if (r.ok !== true || !(Number(r.mudou) > 0)) return [];

const sortear = (lista) => lista[Math.floor(Math.random() * lista.length)];
const ANONIMO = [
  'Combinado!\nNo sistema do restaurante sua resposta aparece sem o seu nome.',
  'Pronto, ficou anônimo.\nNo sistema aparece o que você disse, sem o seu nome.',
  'Tá certo!\nSua resposta fica sem o seu nome no sistema do restaurante.',
];
const MOSTRAR = [
  'Combinado, vai com o seu nome.\nObrigada por confiar!',
  'Pronto, sua resposta aparece com o seu nome.\nObrigada!',
  'Tá certo, obrigada!\nVai com o seu nome.',
];
const texto = sortear(p.escolha === 'anonimo' ? ANONIMO : MOSTRAR);

return [{
  json: {
    telefone: p.telefone,
    baseUrl: p.baseUrl,
    token: p.token,
    texto,
    digitandoMs: 2500 + Math.floor(Math.random() * 3000),
  },
}];
